-- PROSUL: instalar SOMENTE em projeto Supabase novo. Não migra dados CEC/IBFC.
begin;
create table public.prosul_members(id uuid primary key references auth.users(id) on delete cascade,name text not null,email text not null,organization text not null default '',country text not null default '',status text not null default 'pending' check(status in('pending','active','suspended')),role text not null default 'member' check(role in('member','editor','academy','operations','admin')),created_at timestamptz not null default now());
create function public.prosul_register() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin insert into public.prosul_members(id,name,email,organization,country) values(new.id,left(coalesce(new.raw_user_meta_data->>'name','Participante'),150),new.email,left(coalesce(new.raw_user_meta_data->>'organization',''),200),left(coalesce(new.raw_user_meta_data->>'country',''),2));return new;end$$;
create trigger prosul_register after insert on auth.users for each row execute function public.prosul_register();
create function public.prosul_staff() returns boolean language sql stable security definer set search_path=public,pg_temp as $$select coalesce((auth.jwt()->>'aal'='aal2') and exists(select 1 from prosul_members where id=auth.uid() and status='active' and role<>'member'),false)$$;
create function public.prosul_can(k text) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select prosul_staff() and exists(select 1 from prosul_members where id=auth.uid() and (role='admin' or role='editor' and k in('page','news','video','document','event','initiative','opportunity','legislative') or role='academy' and k in('school','journey','program','course','module','lesson','class') or role='operations' and k in('organization','asset','maintenance','inventory','loan')))$$;
create function public.prosul_active() returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from prosul_members where id=auth.uid() and status='active')$$;
create table public.prosul_resources(id uuid primary key default gen_random_uuid(),kind text not null check(kind in('page','news','video','document','event','school','journey','program','course','module','lesson','class','organization','asset','maintenance','inventory','loan','initiative','opportunity','legislative')),title text not null check(length(title) between 3 and 250),summary text not null default '',body text not null default '',country text not null default '',theme text not null default '',parent_id uuid references prosul_resources(id),position integer not null default 0,status text not null default 'draft' check(status in('draft','review','published','archived')),data jsonb not null default '{}',published jsonb,version integer not null default 1,created_by uuid not null references auth.users(id),updated_at timestamptz not null default now());
create unique index prosul_source_unique on prosul_resources ((data->>'source')) where kind='legislative' and nullif(data->>'source','') is not null;
create index prosul_kind_idx on prosul_resources(kind,updated_at desc);create index prosul_parent_idx on prosul_resources(parent_id);
create table public.prosul_audit(id bigint generated always as identity primary key,actor uuid references auth.users(id),action text not null,resource_id uuid,occurred_at timestamptz not null default now(),details jsonb not null default '{}');
create table public.prosul_enrollments(user_id uuid references prosul_members(id) on delete cascade,course_id uuid references prosul_resources(id),created_at timestamptz not null default now(),primary key(user_id,course_id));
create table public.prosul_progress(user_id uuid references prosul_members(id) on delete cascade,lesson_id uuid references prosul_resources(id),completed_at timestamptz not null default now(),primary key(user_id,lesson_id));
create table public.prosul_notes(id uuid primary key default gen_random_uuid(),user_id uuid not null references prosul_members(id) on delete cascade,resource_id uuid references prosul_resources(id),body text not null check(length(body) between 1 and 10000),created_at timestamptz not null default now());
create table public.prosul_registrations(user_id uuid references prosul_members(id) on delete cascade,event_id uuid references prosul_resources(id),created_at timestamptz not null default now(),primary key(user_id,event_id));
create table public.prosul_certificates(code uuid primary key default gen_random_uuid(),user_id uuid not null references prosul_members(id),course_id uuid not null references prosul_resources(id),name text not null,title text not null,hours numeric not null,issued_at timestamptz not null default now(),unique(user_id,course_id));
create table public.prosul_questions(id uuid primary key default gen_random_uuid(),lesson_id uuid not null references prosul_resources(id),prompt text not null,options jsonb not null check(jsonb_typeof(options)='array' and jsonb_array_length(options) between 2 and 6),answer integer not null check(answer>=0),check(answer<jsonb_array_length(options)));
create table public.prosul_attempts(user_id uuid references prosul_members(id),lesson_id uuid references prosul_resources(id),score integer not null,attempted_at timestamptz not null default now(),primary key(user_id,lesson_id));
alter table prosul_members enable row level security;alter table prosul_resources enable row level security;alter table prosul_audit enable row level security;alter table prosul_enrollments enable row level security;alter table prosul_progress enable row level security;alter table prosul_notes enable row level security;alter table prosul_registrations enable row level security;alter table prosul_certificates enable row level security;alter table prosul_questions enable row level security;alter table prosul_attempts enable row level security;
revoke all on prosul_members,prosul_resources,prosul_audit,prosul_enrollments,prosul_progress,prosul_notes,prosul_registrations,prosul_certificates,prosul_questions,prosul_attempts from anon,authenticated;
grant select on prosul_members,prosul_resources,prosul_audit,prosul_enrollments,prosul_progress,prosul_notes,prosul_registrations,prosul_certificates,prosul_attempts to authenticated;
grant insert,delete on prosul_notes to authenticated;
create policy member_read on prosul_members for select to authenticated using(id=auth.uid() or prosul_can('members'));
create policy staff_resources on prosul_resources for select to authenticated using(prosul_can(kind));
create policy staff_audit on prosul_audit for select to authenticated using(prosul_can('members'));
create policy own_enrollments on prosul_enrollments for select to authenticated using(user_id=auth.uid() or prosul_can('course'));
create policy own_progress on prosul_progress for select to authenticated using(user_id=auth.uid() or prosul_can('course'));
create policy own_notes_read on prosul_notes for select to authenticated using(user_id=auth.uid() and prosul_active());
create policy own_notes_write on prosul_notes for insert to authenticated with check(user_id=auth.uid() and prosul_active());
create policy own_notes_delete on prosul_notes for delete to authenticated using(user_id=auth.uid() and prosul_active());
create policy own_registration on prosul_registrations for select to authenticated using(user_id=auth.uid() or prosul_can('event'));
create policy own_certificates on prosul_certificates for select to authenticated using(user_id=auth.uid() or prosul_can('course'));
create policy own_attempts on prosul_attempts for select to authenticated using(user_id=auth.uid());
-- Public projection NEVER exposes a draft or operational asset.
create function public.prosul_feed(p_kind text default null,p_id uuid default null,p_query text default '',p_offset integer default 0) returns setof jsonb language sql stable security definer set search_path=public,pg_temp as $$select published from prosul_resources where published is not null and kind not in('asset','maintenance','inventory','loan') and (kind not in('lesson','module','class') or prosul_active()) and (p_kind is null or kind=p_kind) and (p_id is null or id=p_id) and (coalesce(p_query,'')='' or ((published->>'title')||' '||(published->>'summary')||' '||(published->>'theme')||' '||(published->>'country')) ilike '%'||left(p_query,100)||'%') order by position,updated_at desc,id limit 50 offset greatest(0,least(p_offset,10000))$$;
create function public.prosul_save(p jsonb) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare r prosul_resources;rid uuid;pk text;s text;begin
 if not prosul_can(p->>'kind') then raise exception 'Permissão insuficiente';end if;
 if p->>'id' is not null then select * into r from prosul_resources where id=(p->>'id')::uuid for update;if not found or r.kind<>p->>'kind' or r.version is distinct from (p->>'version')::integer then raise exception 'Conflito de versão';end if;rid=r.id;else rid=gen_random_uuid();end if;
 if nullif(p->>'parent_id','') is not null then select kind into pk from prosul_resources where id=(p->>'parent_id')::uuid;if pk is null or not(case p->>'kind' when 'journey' then pk='school' when 'program' then pk='journey' when 'course' then pk='program' when 'module' then pk='course' when 'lesson' then pk='module' when 'class' then pk='course' when 'maintenance' then pk='asset' when 'inventory' then pk='asset' when 'loan' then pk='asset' else false end) then raise exception 'Vínculo inválido';end if;end if;
 if p->>'kind' in('journey','program','module','lesson','class','maintenance','inventory','loan') and nullif(p->>'parent_id','') is null then raise exception 'Vínculo obrigatório';end if;
 s=coalesce(p->>'status','draft');
 insert into prosul_resources(id,kind,title,summary,body,country,theme,parent_id,position,status,data,created_by) values(rid,p->>'kind',p->>'title',coalesce(p->>'summary',''),coalesce(p->>'body',''),coalesce(p->>'country',''),coalesce(p->>'theme',''),nullif(p->>'parent_id','')::uuid,coalesce((p->>'position')::integer,0),s,coalesce(p->'data','{}'),auth.uid()) on conflict(id) do update set title=excluded.title,summary=excluded.summary,body=excluded.body,country=excluded.country,theme=excluded.theme,parent_id=excluded.parent_id,position=excluded.position,status=excluded.status,data=excluded.data,version=prosul_resources.version+1,updated_at=now();
 if s='published' then update prosul_resources set published=jsonb_build_object('id',id,'kind',kind,'title',title,'summary',summary,'body',body,'country',country,'theme',theme,'parent_id',parent_id,'position',position,'data',data,'version',version,'status','published','updated_at',updated_at) where id=rid;
 elsif s='archived' then update prosul_resources set published=null where id=rid;end if;
 insert into prosul_audit(actor,action,resource_id) values(auth.uid(),'resource.'||s,rid);return rid;
 end$$;
create function public.prosul_member_update(p_id uuid,p_status text,p_role text) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin
 if not prosul_can('members') then raise exception 'Administrador necessário';end if;
 perform pg_advisory_xact_lock(817263);
 if p_id=auth.uid() then raise exception 'Não altere o próprio acesso';end if;
 if exists(select 1 from prosul_members where id=p_id and role='admin' and status='active') and (p_role<>'admin' or p_status<>'active') and (select count(*) from prosul_members where role='admin' and status='active')<=1 then raise exception 'Último administrador';end if;
 update prosul_members set status=p_status,role=p_role where id=p_id;if not found then raise exception 'Membro inexistente';end if;
 insert into prosul_audit(actor,action,resource_id,details) values(auth.uid(),'member.access',p_id,jsonb_build_object('role',p_role,'status',p_status));end$$;
create function public.prosul_enroll(p_course uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin if not prosul_active() or not exists(select 1 from prosul_resources where id=p_course and kind='course' and published is not null) then raise exception 'Curso ou acesso indisponível';end if;insert into prosul_enrollments values(auth.uid(),p_course,now()) on conflict do nothing;end$$;
create function public.prosul_questions(p_lesson uuid) returns table(id uuid,prompt text,options jsonb) language sql stable security definer set search_path=public,pg_temp as $$select q.id,q.prompt,q.options from prosul_questions q join prosul_resources l on l.id=q.lesson_id where q.lesson_id=p_lesson and l.published is not null and prosul_active()$$;
create function public.prosul_question_save(p_lesson uuid,p_prompt text,p_options jsonb,p_answer integer) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin if not prosul_can('lesson') or not exists(select 1 from prosul_resources where id=p_lesson and kind='lesson' and published is null) then raise exception 'Use uma lição ainda não publicada';end if;insert into prosul_questions(lesson_id,prompt,options,answer) values(p_lesson,p_prompt,p_options,p_answer);insert into prosul_audit(actor,action,resource_id) values(auth.uid(),'question.create',p_lesson);end$$;
create function public.prosul_complete(p_lesson uuid,p_answers jsonb default '{}') returns integer language plpgsql security definer set search_path=public,pg_temp as $$declare c uuid;n integer;correct integer;score integer;begin
 if not prosul_active() then raise exception 'Membro ativo necessário';end if;
 select (m.published->>'parent_id')::uuid into c from prosul_resources l join prosul_resources m on m.id=(l.published->>'parent_id')::uuid where l.id=p_lesson and l.kind='lesson' and l.published is not null and m.kind='module' and m.published is not null;
 if c is null or not exists(select 1 from prosul_enrollments e join prosul_resources cr on cr.id=e.course_id where e.user_id=auth.uid() and e.course_id=c and cr.published is not null) then raise exception 'Matricule-se no curso publicado';end if;
 select count(*),count(*) filter(where p_answers->>id::text=answer::text) into n,correct from prosul_questions where lesson_id=p_lesson;score=case when n=0 then 100 else correct*100/n end;
 insert into prosul_attempts values(auth.uid(),p_lesson,score,now()) on conflict(user_id,lesson_id) do update set score=excluded.score,attempted_at=now();
 if score>=70 then insert into prosul_progress values(auth.uid(),p_lesson,now()) on conflict do nothing;end if;return score;end$$;
create function public.prosul_certificate(p_course uuid) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare total integer;done integer;code uuid;begin
 if not prosul_active() or not exists(select 1 from prosul_enrollments where user_id=auth.uid() and course_id=p_course) then raise exception 'Matrícula necessária';end if;
 select count(*),count(pr.lesson_id) into total,done from prosul_resources l join prosul_resources m on m.id=(l.published->>'parent_id')::uuid left join prosul_progress pr on pr.lesson_id=l.id and pr.user_id=auth.uid() where l.kind='lesson' and l.published is not null and m.kind='module' and m.published is not null and m.published->>'parent_id'=p_course::text;
 if total=0 or done<>total then raise exception 'Conclua todas as lições publicadas';end if;
 insert into prosul_certificates(user_id,course_id,name,title,hours) select auth.uid(),r.id,m.name,r.published->>'title',coalesce(nullif(r.published->'data'->>'hours',''),'0')::numeric from prosul_resources r join prosul_members m on m.id=auth.uid() where r.id=p_course and r.kind='course' and r.published is not null on conflict(user_id,course_id) do nothing;
 select c.code into code from prosul_certificates c where c.user_id=auth.uid() and c.course_id=p_course;return code;end$$;
create function public.prosul_certificate_verify(p_code uuid) returns table(name text,title text,hours numeric,issued_at timestamptz) language sql stable security definer set search_path=public,pg_temp as $$select c.name,c.title,c.hours,c.issued_at from prosul_certificates c where c.code=p_code$$;
create function public.prosul_event_register(p_event uuid,p_cancel boolean default false) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin if not prosul_active() then raise exception 'Membro ativo necessário';end if;if p_cancel then delete from prosul_registrations where user_id=auth.uid() and event_id=p_event;return;end if;if not exists(select 1 from prosul_resources where id=p_event and kind='event' and published is not null) then raise exception 'Evento indisponível';end if;insert into prosul_registrations values(auth.uid(),p_event,now()) on conflict do nothing;end$$;
-- Grant only the explicitly declared public RPC surface.
revoke all on function prosul_register() from public,anon,authenticated;
do $$declare r record;begin for r in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'prosul_%' and p.proname<>'prosul_register' loop execute format('revoke all on function %s from public,anon',r.signature);execute format('grant execute on function %s to authenticated',r.signature);end loop;end$$;
grant execute on function prosul_feed(text,uuid,text,integer),prosul_certificate_verify(uuid) to anon;
commit;
